3	public class ValidatorBehavior<TRequest, TResponse> : IPipelineBehavior<TRequest, TResponse> where TRequest : IRequest<TResponse>
4	{
5	    private readonly ILogger<ValidatorBehavior<TRequest, TResponse>> _logger;
6	    private readonly IEnumerable<IValidator<TRequest>> _validators;
7	
8	    public ValidatorBehavior(IEnumerable<IValidator<TRequest>> validators, ILogger<ValidatorBehavior<TRequest, TResponse>> logger)
9	    {
10	        _validators = validators;
11	        _logger = logger;
12	    }
13	
14	    public async Task<TResponse> Handle(TRequest request, RequestHandlerDelegate<TResponse> next, CancellationToken cancellationToken)
15	    {
16	        var typeName = request.GetGenericTypeName();
17	
18	        _logger.LogInformation("Validating command {CommandType}", typeName);
19	
20	        var validationTasks = _validators.Select(v => v.ValidateAsync(request, cancellationToken));
21	        var validationResults = await Task.WhenAll(validationTasks);
22	        
23	        var failures = validationResults
24	            .SelectMany(result => result.Errors)
25	            .Where(error => error != null)
26	            .ToList();
27	
28	        if (failures.Any())
29	        {
30	            _logger.LogWarning("Validation errors - {CommandType} - Command: {@Command} - Errors: {@ValidationErrors}", typeName, request, failures);
31	
32	            throw new OrderingDomainException(
33	                $"Command Validation Errors for type {typeof(TRequest).Name}", new ValidationException("Validation exception", failures));
34	        }
35	
36	        return await next();
37	    }
38	}
